<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};

final class ReplacementSuggestionService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly ControlRoomService $control) {}
    public function preferences(): array {return $this->db->fetchAll('SELECT * FROM deployment_preferences WHERE company_id=:company ORDER BY employee_id LIMIT 1000',['company'=>$this->company()]);}
    public function preference(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['employee_id','expected_revision','max_weekly_minutes','minimum_rest_minutes','base_latitude','base_longitude','max_distance_km']);$employee=$this->row('employees','employee_id',$input['employee_id']??null);$old=$this->db->fetch('SELECT * FROM deployment_preferences WHERE company_id=:company AND employee_id=:employee',['company'=>$this->company(),'employee'=>$employee['employee_id']]);
        if($this->number($input['expected_revision']??null,0)!==(int)($old['revision']??0))throw HttpException::conflict('Deployment preferences changed.');
        $lat=$input['base_latitude']??null;$lng=$input['base_longitude']??null;if($lat===''&&$lng==='')$lat=$lng=null;
        if(($lat===null)!==($lng===null)||($lat!==null&&(!is_numeric($lat)||!is_numeric($lng)||!is_finite((float)$lat)||!is_finite((float)$lng)||abs((float)$lat)>90||abs((float)$lng)>180)))throw HttpException::unprocessable('Provide both valid coordinates, or leave both blank.');
        $values=['company'=>$this->company(),'employee'=>$employee['employee_id'],'weekly'=>$this->number($input['max_weekly_minutes']??null,60,10080),'rest'=>$this->number($input['minimum_rest_minutes']??null,0,2880),'lat'=>$lat,'lng'=>$lng,'distance'=>$this->number($input['max_distance_km']??null,1,2000)];
        if($old)$this->db->execute('UPDATE deployment_preferences SET max_weekly_minutes=:weekly,minimum_rest_minutes=:rest,base_latitude=:lat,base_longitude=:lng,max_distance_km=:distance,revision=revision+1 WHERE company_id=:company AND employee_id=:employee',$values);else $this->db->execute('INSERT INTO deployment_preferences(company_id,employee_id,max_weekly_minutes,minimum_rest_minutes,base_latitude,base_longitude,max_distance_km) VALUES(:company,:employee,:weekly,:rest,:lat,:lng,:distance)',$values);
        $this->audit->record('deployment_preferences','saved',(string)$employee['employee_id']);return ['revision'=>(int)($old['revision']??0)+1];
    });}
    private function distance(float $a,float $b,float $c,float $d): float {$x=sin(deg2rad($c-$a)/2)**2+cos(deg2rad($a))*cos(deg2rad($c))*sin(deg2rad($d-$b)/2)**2;return round(6371*2*asin(sqrt(min(1,$x))),1);}
    public function suggest(string $id): array {
        $shift=$this->row('shift_assignments','shift_assignment_id',$id);if(!empty($shift['deleted_at'])||!in_array($shift['assignment_status'],['PLANNED','ASSIGNED','CONFIRMED','MISSED'],true)||$shift['shift_end_at']<=gmdate('Y-m-d H:i:s')||empty($shift['site_id']))throw HttpException::conflict('Choose an upcoming shift eligible for relief.');$site=$this->site($shift['site_id']);
        $start=strtotime($shift['shift_start_at'].' UTC');$end=strtotime($shift['shift_end_at'].' UTC');if(!$start||!$end||$end<=$start||$end-$start>172800)throw HttpException::unprocessable('Unsupported shift duration.');
        $weekStart=(new \DateTimeImmutable('@'.$start))->setTimezone(new \DateTimeZone('UTC'))->modify('monday this week')->setTime(0,0)->getTimestamp();$weekEnd=$weekStart+7*86400;$repo=new \Sentinel\Repositories\ShiftAssignmentRepository($this->db,$this->context);
        $employees=$this->db->fetchAll("SELECT employee_id FROM employees WHERE company_id=:company AND employment_status='ACTIVE' ORDER BY employee_id LIMIT 1001",['company'=>$this->company()]);if(count($employees)>1000)throw HttpException::unprocessable('Suggestion pool exceeds 1000 employees; narrow the deployment before continuing.');
        $requirements=$this->db->fetchAll('SELECT competency_id FROM site_training_requirements WHERE company_id=:company AND site_id=:site AND removed_at IS NULL',['company'=>$this->company(),'site'=>$site['site_id']]);$eligible=[];$excluded=[];
        foreach($employees as$e){$employee=(string)$e['employee_id'];if($employee===(string)$shift['employee_id'])continue;$reasons=[];if(!$repo->employeeIsGuard($employee))continue;
            $p=$this->db->fetch('SELECT * FROM deployment_preferences WHERE company_id=:company AND employee_id=:employee',['company'=>$this->company(),'employee'=>$employee])??['max_weekly_minutes'=>2880,'minimum_rest_minutes'=>660,'base_latitude'=>null,'base_longitude'=>null,'max_distance_km'=>200];
            if($this->db->fetch("SELECT availability_id FROM employee_availability WHERE company_id=:company AND employee_id=:employee AND state='APPROVED' AND starts_at<:end AND ends_at>:start",['company'=>$this->company(),'employee'=>$employee,'start'=>$shift['shift_start_at'],'end'=>$shift['shift_end_at']]))$reasons[]='APPROVED_ABSENCE';
            foreach($requirements as$r)if(!$this->db->fetch('SELECT training_id FROM employee_training WHERE company_id=:company AND employee_id=:employee AND competency_id=:competency AND verified_at IS NOT NULL AND revoked_at IS NULL AND valid_from<=:start AND valid_until>=:end',['company'=>$this->company(),'employee'=>$employee,'competency'=>$r['competency_id'],'start'=>gmdate('Y-m-d',$start),'end'=>gmdate('Y-m-d',$end)]))$reasons[]='MISSING_VALID_TRAINING';
            $other=$this->db->fetchAll("SELECT shift_start_at,shift_end_at FROM shift_assignments WHERE company_id=:company AND employee_id=:employee AND shift_assignment_id<>:id AND deleted_at IS NULL AND assignment_status IN ('PLANNED','ASSIGNED','CONFIRMED','IN_PROGRESS','COMPLETED') AND shift_start_at<:until AND shift_end_at>:since LIMIT 1001",['company'=>$this->company(),'employee'=>$employee,'id'=>$id,'since'=>gmdate('Y-m-d H:i:s',min($weekStart,$start-2880*60)),'until'=>gmdate('Y-m-d H:i:s',max($weekEnd,$end+2880*60))]);
            if(count($other)>1000)$reasons[]='ROSTER_TOO_LARGE';$seconds=max(0,min($end,$weekEnd)-max($start,$weekStart));
            foreach($other as$o){$a=strtotime($o['shift_start_at'].' UTC');$b=strtotime($o['shift_end_at'].' UTC');if(!$a||!$b||$b<=$a||$b-$a>172800){$reasons[]='INVALID_ROSTER_DATA';continue;}$seconds+=max(0,min($b,$weekEnd)-max($a,$weekStart));if($a<$end&&$b>$start)$reasons[]='SHIFT_OVERLAP';elseif(($b<=$start&&$start-$b<(int)$p['minimum_rest_minutes']*60)||($a>=$end&&$a-$end<(int)$p['minimum_rest_minutes']*60))$reasons[]='REST_LIMIT';}
            $minutes=(int)ceil($seconds/60);if($minutes>(int)$p['max_weekly_minutes'])$reasons[]='WEEKLY_LIMIT';
            // Also check the following UTC week for a shift crossing its boundary.
            if($end>$weekEnd){$next=$this->db->fetchAll("SELECT shift_start_at,shift_end_at FROM shift_assignments WHERE company_id=:company AND employee_id=:employee AND shift_assignment_id<>:id AND deleted_at IS NULL AND assignment_status IN ('PLANNED','ASSIGNED','CONFIRMED','IN_PROGRESS','COMPLETED') AND shift_start_at<:end AND shift_end_at>:start",['company'=>$this->company(),'employee'=>$employee,'id'=>$id,'start'=>gmdate('Y-m-d H:i:s',$weekEnd),'end'=>gmdate('Y-m-d H:i:s',$weekEnd+7*86400)]);$n=$end-$weekEnd;foreach($next as$o)$n+=max(0,min(strtotime($o['shift_end_at'].' UTC'),$weekEnd+7*86400)-max(strtotime($o['shift_start_at'].' UTC'),$weekEnd));if(ceil($n/60)>(int)$p['max_weekly_minutes'])$reasons[]='NEXT_WEEK_LIMIT';}
            $distance=null;if($p['base_latitude']!==null&&isset($site['latitude'],$site['longitude'])){$distance=$this->distance((float)$p['base_latitude'],(float)$p['base_longitude'],(float)$site['latitude'],(float)$site['longitude']);if($distance>(int)$p['max_distance_km'])$reasons[]='DISTANCE_LIMIT';}
            $row=['employee_id'=>$employee,'scheduled_week_minutes_with_replacement'=>$minutes,'weekly_limit_minutes'=>(int)$p['max_weekly_minutes'],'minimum_rest_minutes'=>(int)$p['minimum_rest_minutes'],'straight_line_km'=>$distance,'distance_known'=>$distance!==null];if($reasons)$excluded[]=$row+['reasons'=>array_values(array_unique($reasons))];else $eligible[]=$row;
        }
        usort($eligible,static fn($a,$b)=>[$a['straight_line_km']??INF,$a['scheduled_week_minutes_with_replacement'],$a['employee_id']]<=>[$b['straight_line_km']??INF,$b['scheduled_week_minutes_with_replacement'],$b['employee_id']]);
        return ['shift_id'=>$id,'expected_employee_id'=>(string)$shift['employee_id'],'eligible'=>$eligible,'excluded'=>$excluded,'generated_at'=>gmdate('Y-m-d H:i:s'),'note'=>'Suggestions use recorded qualifications, approved absence, scheduled UTC-week hours, rest and optional straight-line distance. Defaults are company planning settings, not legal entitlement calculations. A manager must approve; travel time and actual availability need confirmation.'];
    }
    public function approve(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['expected_employee_id','replacement_employee_id','reason']);$suggestions=$this->suggest($id);$employee=(string)$this->number($input['replacement_employee_id']??null);if(!in_array($employee,array_column($suggestions['eligible'],'employee_id'),true))throw HttpException::conflict('The replacement is no longer eligible. Refresh suggestions.');return $this->control->relief($id,$input);
    });}
}
